
from __future__ import annotations

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
HTML = ROOT / "docs" / "index.html"
SCRIPT_BLOCK = '<script id="ml-performance-rank-enhancer">\n(function(){\n  const MODEL_ORDER=[\'Ensemble\',\'Score Top\',\'Ridge\',\'Random Forest\',\'Extra Trees\',\'XGBoost\',\'LightGBM\',\'CatBoost\'];\n\n  function addStyle(){\n    if(document.getElementById(\'mlPerformanceRankStyle\')) return;\n    const style=document.createElement(\'style\');\n    style.id=\'mlPerformanceRankStyle\';\n    style.textContent=`\n      .ml-rank-badge{display:inline-flex;align-items:center;justify-content:center;min-width:32px;height:26px;padding:0 8px;border-radius:999px;background:rgba(34,197,94,.12);border:1px solid rgba(34,197,94,.35);color:#86efac;font-weight:900;margin-right:10px;font-size:.82rem}\n      .ml-summary-name{display:flex;align-items:center;gap:0}\n      .ml-model-perf-name{display:flex;align-items:center;white-space:nowrap}\n      .ml-perf-sub{display:block;color:var(--muted);font-size:.78rem;margin-top:2px;font-weight:600}\n      .ml-perf-status{display:inline-flex;align-items:center;border-radius:999px;padding:4px 8px;font-weight:800;font-size:.78rem;border:1px solid rgba(148,163,184,.22)}\n      .ml-perf-status.ok{color:#86efac;background:rgba(34,197,94,.10);border-color:rgba(34,197,94,.28)}\n      .ml-perf-status.warm{color:#fbbf24;background:rgba(251,191,36,.10);border-color:rgba(251,191,36,.28)}\n      .ml-perf-status.na{color:#94a3b8;background:rgba(148,163,184,.08)}\n      .ml-perf-help{margin:10px 0 14px;color:var(--muted);font-size:.9rem;line-height:1.45}\n      .ml-perf-help b{color:var(--text)}\n    `;\n    document.head.appendChild(style);\n  }\n\n  function asNumber(v){\n    if(v===null || v===undefined || v===\'\') return null;\n    if(typeof v===\'number\') return Number.isFinite(v) ? v : null;\n    let s=String(v).trim();\n    if(!s || [\'nan\',\'none\',\'null\',\'-\',\'—\',\'<na>\'].includes(s.toLowerCase())) return null;\n    s=s.replace(\'R$\',\'\').replace(\'%\',\'\').replace(/\\s/g,\'\');\n    s=s.replace(/[^0-9,.\\-+]/g,\'\');\n    if(!s || [\',\',\'.\',\'-\',\'+\'].includes(s)) return null;\n    if(s.includes(\',\') && s.includes(\'.\')){\n      if(s.lastIndexOf(\',\') > s.lastIndexOf(\'.\')) s=s.replace(/\\./g,\'\').replace(\',\',\'.\');\n      else s=s.replace(/,/g,\'\');\n    }else if(s.includes(\',\')){\n      s=s.replace(/\\./g,\'\').replace(\',\',\'.\');\n    }else{\n      const parts=s.split(\'.\');\n      if(parts.length>2) s=parts.slice(0,-1).join(\'\')+\'.\'+parts.at(-1);\n    }\n    const n=Number(s);\n    return Number.isFinite(n) ? n : null;\n  }\n\n  function avg(values){\n    const nums=values.map(asNumber).filter(v=>v!==null);\n    if(!nums.length) return null;\n    return nums.reduce((a,b)=>a+b,0)/nums.length;\n  }\n\n  function max(values){\n    const nums=values.map(asNumber).filter(v=>v!==null);\n    if(!nums.length) return null;\n    return Math.max(...nums);\n  }\n\n  function fmtNum(v,d=2){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    return n.toLocaleString(\'pt-BR\',{minimumFractionDigits:d,maximumFractionDigits:d});\n  }\n\n  function fmtPct(v){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    const pct=Math.abs(n)<=1.5 ? n*100 : n;\n    return (pct>0?\'+\':\'\')+pct.toLocaleString(\'pt-BR\',{minimumFractionDigits:2,maximumFractionDigits:2})+\'%\';\n  }\n\n  function fmtHit(v){\n    const n=asNumber(v);\n    if(n===null) return \'—\';\n    const pct=Math.abs(n)<=1.5 ? n*100 : n;\n    return pct.toLocaleString(\'pt-BR\',{minimumFractionDigits:2,maximumFractionDigits:2})+\'%\';\n  }\n\n  function cleanModelName(v){\n    if(!v) return null;\n    const s=String(v).trim();\n    const found=MODEL_ORDER.find(m=>m.toLowerCase()===s.toLowerCase());\n    return found || s;\n  }\n\n  function statusClass(status){\n    const s=String(status||\'\').toLowerCase();\n    if(s.includes(\'ativo\') || s.includes(\'ok\')) return \'ok\';\n    if(s.includes(\'aquec\') || s.includes(\'matur\')) return \'warm\';\n    return \'na\';\n  }\n\n  function payloadFromState(){\n    try{\n      if(typeof state!==\'undefined\' && state && state.data && state.data.modelos_ml) return state.data;\n    }catch(e){}\n    return null;\n  }\n\n  async function loadPayload(){\n    const s=payloadFromState();\n    if(s) return s;\n    try{\n      const idx=await fetch(\'data/index.json\',{cache:\'no-store\'}).then(r=>r.json());\n      const latest=[...idx].sort().at(-1);\n      return await fetch(`data/${latest}.json`,{cache:\'no-store\'}).then(r=>r.json());\n    }catch(e){\n      return null;\n    }\n  }\n\n  function getPerfRows(ml){\n    const rows=Array.isArray(ml?.performance) ? ml.performance : [];\n    return rows.map(r=>{\n      const model=cleanModelName(r.Modelo ?? r.modelo ?? r.model);\n      if(!model) return null;\n      return {\n        raw:r,\n        model,\n        type:String(r.Tipo ?? r.tipo ?? r.Classe ?? r.classe ?? \'—\').replace(\'ACAO\',\'Ações\').replace(\'FII\',\'FIIs\'),\n        horizon:String(r.Horizonte ?? r.horizonte ?? ml?.horizonte_principal ?? \'7d\'),\n        retorno:asNumber(r.Retorno_Medio_Top20 ?? r.retorno_medio_top20 ?? r.retorno_medio ?? r.Return_Top20),\n        hit:asNumber(r.Hit_Rate_Top20 ?? r.hit_rate_top20 ?? r.hit_rate ?? r.Hit_Rate),\n        spearman:asNumber(r.Spearman_IC ?? r.spearman_ic ?? r.IC),\n        alpha:asNumber(r.Alpha_vs_Score_Top ?? r.alpha_vs_score_top ?? r.Alpha),\n        confianca:asNumber(r.Confiabilidade_Pct ?? r.confiabilidade_pct ?? r.Confiabilidade),\n        janelas:asNumber(r.Janelas_Validas ?? r.janelas_validas ?? r.Valid_Windows ?? r.valid_windows),\n        status:String(r.Status ?? r.status ?? r.status_modelos ?? \'—\')\n      };\n    }).filter(Boolean);\n  }\n\n  function modelStats(ml){\n    const perf=getPerfRows(ml);\n    const byModel=new Map();\n\n    for(const row of perf){\n      if(!byModel.has(row.model)){\n        byModel.set(row.model,{model:row.model,types:new Set(),horizons:new Set(),rows:[],order:MODEL_ORDER.indexOf(row.model)});\n      }\n      const g=byModel.get(row.model);\n      g.rows.push(row);\n      if(row.type && row.type!==\'—\') g.types.add(row.type);\n      if(row.horizon) g.horizons.add(row.horizon);\n    }\n\n    // Garante que modelos sem estatística ainda apareçam no ranking, mas no fim.\n    for(const model of MODEL_ORDER){\n      if(!byModel.has(model)){\n        byModel.set(model,{model,types:new Set(),horizons:new Set(),rows:[],order:MODEL_ORDER.indexOf(model)});\n      }\n    }\n\n    const stats=[...byModel.values()].map(g=>{\n      const rows=g.rows;\n      const out={\n        model:g.model,\n        types:[...g.types],\n        horizons:[...g.horizons],\n        retorno:avg(rows.map(r=>r.retorno)),\n        hit:avg(rows.map(r=>r.hit)),\n        spearman:avg(rows.map(r=>r.spearman)),\n        alpha:avg(rows.map(r=>r.alpha)),\n        confianca:avg(rows.map(r=>r.confianca)),\n        janelas:max(rows.map(r=>r.janelas)),\n        status:rows.some(r=>String(r.status).toLowerCase().includes(\'ativo\')) ? \'Ativo\' : (rows.length ? rows[0].status : \'Sem medição\'),\n        measured:rows.some(r=>[r.retorno,r.hit,r.spearman,r.alpha,r.confianca].some(v=>v!==null)),\n        order:g.order<0 ? 999 : g.order\n      };\n\n      // Score usado só para ordenação. Prioriza alpha e hit rate; depois IC e retorno.\n      out.sortScore =\n        (out.alpha ?? -999) * 1000 +\n        (out.hit ?? -999) * 100 +\n        (out.spearman ?? -999) * 50 +\n        (out.retorno ?? -999) * 10 +\n        (out.confianca ?? 0);\n\n      return out;\n    });\n\n    stats.sort((a,b)=>{\n      if(a.measured !== b.measured) return a.measured ? -1 : 1;\n      if(b.sortScore !== a.sortScore) return b.sortScore - a.sortScore;\n      return a.order - b.order;\n    });\n\n    stats.forEach((s,i)=>s.rank=i+1);\n    return stats;\n  }\n\n  function renderPerformance(ml, stats){\n    const body=document.getElementById(\'mlPerformanceBody\');\n    if(!body) return;\n\n    const table=body.closest(\'table\');\n    if(table){\n      const thead=table.querySelector(\'thead\');\n      if(thead){\n        thead.innerHTML=`\n          <tr>\n            <th>Rank</th>\n            <th>Modelo</th>\n            <th>Tipos</th>\n            <th>Horizonte</th>\n            <th>Retorno médio Top20</th>\n            <th>Hit rate</th>\n            <th>Spearman IC</th>\n            <th>Alpha vs Score Top</th>\n            <th>Janelas</th>\n            <th>Status</th>\n          </tr>`;\n      }\n    }\n\n    let note=document.getElementById(\'mlPerformanceRankNote\');\n    if(!note && table){\n      note=document.createElement(\'div\');\n      note.id=\'mlPerformanceRankNote\';\n      note.className=\'ml-perf-help\';\n      note.innerHTML=\'<b>Ranking:</b> ordenado do melhor para o pior modelo, priorizando Alpha vs Score Top, Hit Rate, Spearman IC e retorno médio do Top 20. Modelos sem estatística suficiente ficam no fim.\';\n      table.insertAdjacentElement(\'beforebegin\',note);\n    }\n\n    body.innerHTML=stats.map(s=>`\n      <tr>\n        <td><span class="ml-rank-badge">#${s.rank}</span></td>\n        <td>\n          <div class="ml-model-perf-name"><b>${s.model}</b></div>\n          <span class="ml-perf-sub">${s.measured ? \'com estatística calculada\' : \'aguardando medição\'}</span>\n        </td>\n        <td>${s.types.length ? s.types.join(\' / \') : \'—\'}</td>\n        <td>${s.horizons.length ? s.horizons.join(\' / \') : (ml.horizonte_principal || \'7d\')}</td>\n        <td class="num">${fmtPct(s.retorno)}</td>\n        <td class="num">${fmtHit(s.hit)}</td>\n        <td class="num">${fmtNum(s.spearman,3)}</td>\n        <td class="num">${fmtPct(s.alpha)}</td>\n        <td class="num">${fmtNum(s.janelas,0)}</td>\n        <td><span class="ml-perf-status ${statusClass(s.status)}">${s.status || \'—\'}</span></td>\n      </tr>\n    `).join(\'\');\n  }\n\n  function findModelInSummary(summary){\n    const txt=summary.textContent || \'\';\n    return MODEL_ORDER.find(m=>txt.toLowerCase().includes(m.toLowerCase()));\n  }\n\n  function decorateSummaries(stats){\n    const rankByModel=new Map(stats.map(s=>[s.model,s.rank]));\n    const selectors=[\n      \'#staticMlModelTables details summary\',\n      \'#forceMlModelByModelGrid details summary\',\n      \'#mlModelByModelGrid details summary\'\n    ];\n\n    selectors.forEach(sel=>{\n      document.querySelectorAll(sel).forEach(summary=>{\n        const model=findModelInSummary(summary);\n        if(!model) return;\n\n        const rank=rankByModel.get(model);\n        const meta=summary.querySelector(\'span:not(.ml-rank-badge)\');\n        const metaText=meta ? meta.outerHTML : \'\';\n        summary.innerHTML=`<div class="ml-summary-name"><span class="ml-rank-badge">#${rank || \'—\'}</span>${model}</div>${metaText}`;\n        summary.dataset.modelRank=rank || \'999\';\n      });\n    });\n\n    // Reordena os blocos do Top 20 por modelo do melhor para o pior.\n    [\'staticMlModelTables\',\'forceMlModelByModelGrid\',\'mlModelByModelGrid\'].forEach(id=>{\n      const container=document.getElementById(id);\n      if(!container) return;\n      const details=[...container.querySelectorAll(\':scope > details\')];\n      if(details.length<2) return;\n      details.sort((a,b)=>{\n        const ra=Number(a.querySelector(\'summary\')?.dataset.modelRank || 999);\n        const rb=Number(b.querySelector(\'summary\')?.dataset.modelRank || 999);\n        return ra-rb;\n      });\n      details.forEach(d=>container.appendChild(d));\n    });\n  }\n\n  async function run(){\n    addStyle();\n    const payload=await loadPayload();\n    const ml=payload?.modelos_ml;\n    if(!ml) return;\n\n    const stats=modelStats(ml);\n    renderPerformance(ml,stats);\n    decorateSummaries(stats);\n  }\n\n  document.addEventListener(\'DOMContentLoaded\',()=>{run(); setTimeout(run,500); setTimeout(run,1500); setTimeout(run,3000);});\n  document.addEventListener(\'click\',e=>{\n    if(e.target && (e.target.closest(\'.tab\') || e.target.closest(\'[data-tab]\') || e.target.closest(\'button\') || e.target.closest(\'summary\'))){\n      setTimeout(run,250);\n    }\n  });\n\n  const observer=new MutationObserver(()=>{ setTimeout(run,100); });\n  observer.observe(document.documentElement,{childList:true,subtree:true});\n\n  run();\n})();\n</script>'


def main() -> None:
    if not HTML.exists():
        raise FileNotFoundError(f"Não encontrei {HTML}")

    text = HTML.read_text(encoding="utf-8")

    text = re.sub(
        r"\n?<script id=\"ml-performance-rank-enhancer\">.*?</script>\n?",
        "\n",
        text,
        flags=re.S,
    )

    idx = text.lower().rfind("</body>")
    if idx >= 0:
        text = text[:idx] + "\n" + SCRIPT_BLOCK + "\n" + text[idx:]
    else:
        text = text.rstrip() + "\n" + SCRIPT_BLOCK + "\n"

    HTML.write_text(text, encoding="utf-8")
    print("[OK] Ranking de performance por modelo aplicado.")
    print("[OK] A tabela 'Performance dos modelos' será reordenada do melhor para o pior.")
    print("[OK] O rank aparecerá ao lado do nome do modelo no Top 20 por modelo.")


if __name__ == "__main__":
    main()
